function character(input: Omit<StoryCharacterDefinition, 'schedules'> & { schedules: Array<[string, number, number, string]> }): StoryCharacterDefinition {
  return { ...input, schedules: input.schedules.map(([locationId, startsAt, endsAt, activity]) => ({ locationId, startsAt, endsAt, activity })) };
}

