export function storyDefinition(slug: string): StoryDefinition | null {
  return slug === LAST_NIGHT_IN_VESPORMOOR.slug ? LAST_NIGHT_IN_VESPORMOOR : null;
}

export function assertLastNightContent(): void {
  if (LAST_NIGHT_IN_VESPORMOOR.evidence.length !== 40) throw new Error(`last_night_evidence_count:${LAST_NIGHT_IN_VESPORMOOR.evidence.length}`);
  if (LAST_NIGHT_IN_VESPORMOOR.evidence.filter((item) => item.kind === 'critical').length !== 20) throw new Error('last_night_critical_evidence_count');
  if (LAST_NIGHT_IN_VESPORMOOR.evidence.filter((item) => item.kind === 'character_truth').length !== 12) throw new Error('last_night_character_truth_count');
  if (LAST_NIGHT_IN_VESPORMOOR.evidence.filter((item) => item.kind === 'atmosphere').length !== 8) throw new Error('last_night_atmosphere_count');
  if (LAST_NIGHT_IN_VESPORMOOR.endings.length !== 4) throw new Error('last_night_ending_count');
  if (LAST_NIGHT_IN_VESPORMOOR.characters.filter((item) => item.storyProfile?.participationTier === 'core').length !== 12) throw new Error('last_night_core_character_count');
  if (LAST_NIGHT_IN_VESPORMOOR.knownBaseCharacterIds?.length !== 47) throw new Error('last_night_character_coverage');
  if (LAST_NIGHT_IN_VESPORMOOR.knownBaseLocationIds?.length !== 51) throw new Error('last_night_location_coverage');
  const errors = validateStoryDefinition(LAST_NIGHT_IN_VESPORMOOR);
  if (errors.length) throw new Error(`last_night_invalid_references:${errors.join(',')}`);
}

assertLastNightContent();
